  @protected
  void sse_encode_bridge_player_command(
    BridgePlayerCommand self,
    SseSerializer serializer,
  ) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    switch (self) {
      case BridgePlayerCommand_Play(trackId: final trackId):
        sse_encode_i_32(0, serializer);
        sse_encode_String(trackId, serializer);
      case BridgePlayerCommand_PlayTrack(track: final track):
        sse_encode_i_32(1, serializer);
        sse_encode_box_autoadd_bridge_track(track, serializer);
      case BridgePlayerCommand_PlayQueue(
        tracks: final tracks,
        startIndex: final startIndex,
      ):
        sse_encode_i_32(2, serializer);
        sse_encode_list_bridge_track(tracks, serializer);
        sse_encode_i_32(startIndex, serializer);
      case BridgePlayerCommand_Pause():
        sse_encode_i_32(3, serializer);
      case BridgePlayerCommand_Resume():
        sse_encode_i_32(4, serializer);
      case BridgePlayerCommand_Toggle():
        sse_encode_i_32(5, serializer);
      case BridgePlayerCommand_Next():
        sse_encode_i_32(6, serializer);
      case BridgePlayerCommand_Previous():
        sse_encode_i_32(7, serializer);
      case BridgePlayerCommand_Seek(positionMs: final positionMs):
        sse_encode_i_32(8, serializer);
        sse_encode_i_64(positionMs, serializer);
      case BridgePlayerCommand_SetVolume(volume: final volume):
        sse_encode_i_32(9, serializer);
        sse_encode_f_64(volume, serializer);
      case BridgePlayerCommand_SetShuffle(enabled: final enabled):
        sse_encode_i_32(10, serializer);
        sse_encode_bool(enabled, serializer);
      case BridgePlayerCommand_SetRepeat(mode: final mode):
        sse_encode_i_32(11, serializer);
        sse_encode_bridge_repeat_mode(mode, serializer);
      case BridgePlayerCommand_ClearQueue():
        sse_encode_i_32(12, serializer);
      case BridgePlayerCommand_RequestSnapshot():
        sse_encode_i_32(13, serializer);
    }
  }

